<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Betna Studio</title><link rel="icon" href="/betna-mark.svg" type="image/svg+xml">
<style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 12% 12%,#ede9fe,transparent 50%),radial-gradient(ellipse at 90% 92%,#e9d5ff,transparent 55%),#faf8ff;font-family:Inter,system-ui,-apple-system,sans-serif;color:#231338;padding:24px}
main{width:min(100%,500px);background:#fff;border:1px solid #e9def7;box-shadow:0 26px 90px #4c1d951a;border-radius:26px;padding:44px;text-align:center}
.logo{display:inline-grid;place-items:center;width:76px;height:76px;background:linear-gradient(135deg,#7c3aed,#4c1d95);border-radius:22px;color:#fff;font-size:48px;font-weight:900;box-shadow:0 10px 26px #6d28d934}
h1{font-size:36px;letter-spacing:-1.5px;margin:24px 0 8px}p{color:#716783;font-size:15px;line-height:1.7;margin-bottom:28px}
a{display:inline-flex;align-items:center;justify-content:center;gap:10px;background:#6d28d9;border-radius:12px;padding:15px 26px;color:#fff;text-decoration:none;font-size:14px;font-weight:750}a:hover{background:#5b21b6}a:focus-visible{outline:3px solid #c4b5fd;outline-offset:3px}
small{display:block;margin-top:24px;color:#9388a8}
</style></head><body><main><span class="logo">B</span><h1>Betna Studio</h1><p>Your Telegram audience and messaging workspace.</p><a href="/admin">Open admin workspace →</a><small>Betna · Powered by Laravel</small></main></body></html>
